// Usa o catálogo guardado por 15 min para não gastar chamada do Airtable a cada mensagem
const sd = $getWorkflowStaticData('global');
const cache_ok = Array.isArray(sd.catalogo) && sd.catalogo.length > 0 && Array.isArray(sd.trocas) && sd.trocas.length > 0 && sd.catalogoVer === 3 && (Date.now() - (sd.catalogoTs || 0)) < 15 * 60 * 1000;
return [{ json: { cache_ok, t0: Date.now() } }];

// Guarda o catálogo (só produtos ativos) e as trocas aprovadas para as próximas mensagens
const sd = $getWorkflowStaticData('global');
sd.catalogo = $('Buscar catálogo').all().map(i => i.json.fields ?? i.json).filter(p => p.Produto && p.SKU);
const skuPorId = Object.fromEntries(sd.catalogo.map(p => [p.id, p.SKU]));
sd.trocas = $('Buscar trocas').all().map(i => i.json.fields ?? i.json).filter(t => t.Ingrediente).map(t => ({
  ingrediente: t.Ingrediente,
  skus: (t.Troca || []).map(id => skuPorId[id]).filter(Boolean),
  muda: t['O que muda no prato'] || '',
  risco: String(t.Risco || 'Leve')
}));
// Apelidos aprendidos: os oficiais entram em "Como o povo chama"; os rejeitados ficam marcados para nunca voltar
sd.aprendStatus = {};
for (const i of $('Buscar aprendizados').all()) {
  const a = i.json.fields ?? i.json;
  if (!a.Chave) continue;
  sd.aprendStatus[a.Chave] = a.Status;
  if (a.Status !== 'Oficial') continue;
  const [frase, sku] = a.Chave.split('|');
  const p = sd.catalogo.find(x => x.SKU === sku);
  if (p && !String(p['Como o povo chama'] || '').includes(frase)) p['Como o povo chama'] = (p['Como o povo chama'] ? p['Como o povo chama'] + ', ' : '') + frase;
}
sd.catalogoTs = Date.now();
sd.catalogoVer = 3; // mude este número para forçar a leitura do catálogo na próxima mensagem
return [{ json: { produtos: sd.catalogo.length, trocas: sd.trocas.length } }];

// Decide o que fazer com a mensagem: regra fixa (menu, categoria, carrinho, fechar) ou IA
const sd = $getWorkflowStaticData('global');
const chat = $('Mensagem no chat').first().json;
const sessao = chat.sessionId || 'teste';
// Foto da lista ou áudio: a mensagem vira um marcador e o texto lido entra no lugar dele depois
const temMidia = Object.keys($('Mensagem no chat').first().binary || {}).length > 0;
const msgRaw = temMidia ? '%%MIDIA%%' : (chat.chatInput || '').trim();
const norm = s => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const msg = norm(msgRaw).replace(/[!?.]+$/, '');
const reais = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const ORDEM = ['Bebidas', 'Mercearia', 'Frios e laticínios', 'Hortifruti', 'Carnes', 'Congelados', 'Snacks', 'Doces', 'Limpeza', 'Higiene e farmácia'];

// Memória da conversa (carrinho de cada cliente). Apaga conversas paradas há mais de 24 h.
sd.sessoes = sd.sessoes || {};
for (const [k, v] of Object.entries(sd.sessoes)) if (Date.now() - v.ts > 24 * 3600 * 1000) delete sd.sessoes[k];
const s = sd.sessoes[sessao] = sd.sessoes[sessao] || { carrinho: {}, ultima: '', aguardando18: null, maior18: false, msgs: 0, inicio: Date.now() };
s.ts = Date.now();
s.msgs += 1;

const produtos = sd.catalogo || [];
const porSku = Object.fromEntries(produtos.map(p => [p.SKU, p]));
const cats = ORDEM.filter(c => produtos.some(p => p.Categoria === c));
produtos.forEach(p => { if (p.Categoria && !cats.includes(p.Categoria)) cats.push(p.Categoria); });

const linha = p => `- ${p.Produto} (${p.Marca}, ${p.Unidade}): ${reais(p['Preço'])}` + ((p.Estoque ?? 1) <= 0 ? ' (acabou)' : '');
const verCarrinho = () => {
  const itens = Object.entries(s.carrinho).filter(([sku]) => porSku[sku]);
  if (!itens.length) return 'Seu carrinho está vazio.';
  let total = 0;
  const linhas = itens.map(([sku, q]) => { const p = porSku[sku]; const sub = q * Number(p['Preço']); total += sub; return `- ${q}x ${p.Produto} ${reais(sub)}`; });
  return '🛒 *Seu carrinho*\n\n' + linhas.join('\n') + `\n\n*Total: ${reais(total)}*`;
};
const menu = () => 'Oi! Aqui é o Tá Faltando?, o mercadinho que entrega rapidinho.\n\n' +
  'Me fala o que você precisa do seu jeito (ex.: "2 coca e um miojo de tomate") ou escolha uma categoria pelo número:\n\n' +
  cats.map((c, i) => `${i + 1}. ${c}`).join('\n') +
  '\n\nSem ideia do que pedir? Digite "me dá uma ideia".' +
  (Object.keys(s.carrinho).length ? '\n\n' + verCarrinho() : '');

const saudacoes = ['oi', 'oie', 'ola', 'opa', 'eai', 'e ai', 'bom dia', 'boa tarde', 'boa noite', 'menu', 'cardapio', 'inicio', 'comecar'];
// Só é saudação se não sobrar pedido depois do "oi" (ex.: "oi, quero 2 coca" vai para a IA)
const resto = saudacoes.reduce((m, x) => m.replace(new RegExp('^' + x + '(?![a-z])[\\s!,.?]*'), ''), msg).replace(/^(tudo bem|td bem|blz|beleza)[\s!,.?]*/, '').trim();
const ehSaudacao = !msg || !resto;
const pediuDespensa = ['despensa', 'minha despensa', 'ver despensa', 'o que eu tenho em casa', 'o que tenho em casa'].includes(msg);
const pediuCarrinho = ['carrinho', 'ver carrinho', 'meu carrinho', 'meu pedido', 'ver pedido'].includes(msg);
const pediuLimpar = ['limpar', 'limpar carrinho', 'esvaziar', 'esvaziar carrinho', 'cancelar', 'cancelar pedido', 'zerar'].includes(msg);
const pediuFechar = ['fechar', 'fechar pedido', 'finalizar', 'finalizar pedido', 'pagar', 'so isso', 'e so isso', 'pode fechar'].includes(msg);

let saida = null;
// Resposta à pergunta de +18
if (s.aguardando18) {
  if (/^(sim|s|tenho|confirmo|sou maior)/.test(msg)) {
    for (const it of s.aguardando18) s.carrinho[it.sku] = (s.carrinho[it.sku] || 0) + it.qtd;
    s.maior18 = true;
    s.aguardando18 = null;
    saida = 'Valeu! Coloquei no carrinho.\n\n' + verCarrinho() + '\n\nQuer mais alguma coisa? Para fechar, digite "fechar".';
  } else if (/^(nao|n)\b/.test(msg)) {
    s.aguardando18 = null;
    saida = 'Sem problema, deixei de fora.\n\n' + verCarrinho();
  } else {
    s.aguardando18 = null;
  }
}
// "Me dá uma ideia": 2 perguntas (pra quê e pra quantos) e 3 combos montados por regra com o que tem em estoque. Sem IA.
const IDEIAS = {
  jantar: { nome: 'jantar rápido', combos: [
    ['Macarrão à bolonhesa', [['MER-01', 1 / 4], ['CAR-01', 1 / 3], ['MER-04', 1 / 3], ['FRI-02', 0], ['BEB-02', 1 / 4]]],
    ['Arroz, feijão e ovo', [['MER-05', 1 / 5], ['MER-06', 1 / 5], ['FRI-06', 1 / 6], ['HOR-01', 0], ['HOR-02', 0]]],
    ['Miojo turbinado', [['MER-03', 1], ['FRI-06', 1 / 6], ['FRI-02', 0], ['BEB-03', 1]]],
  ] },
  cafe: { nome: 'café da manhã', combos: [
    ['Pão com manteiga e achocolatado', [['MER-14', 1 / 4], ['FRI-05', 0], ['FRI-01', 1 / 2], ['MER-12', 0]]],
    ['Ovos mexidos com pão e suco', [['FRI-06', 1 / 6], ['MER-14', 1 / 4], ['FRI-05', 0], ['BEB-07', 1 / 3]]],
    ['Leve: iogurte, suco e biscoito', [['FRI-04', 1 / 6], ['BEB-07', 1 / 3], ['DOC-04', 1 / 2]]],
  ] },
  lanche: { nome: 'lanche ou petisco', combos: [
    ['Sessão de filme', [['SNK-03', 1 / 2], ['BEB-02', 1 / 4], ['DOC-01', 1 / 2]]],
    ['Petisco salgado', [['SNK-01', 1 / 2], ['SNK-02', 1 / 2], ['SNK-04', 1 / 3], ['BEB-01', 1]]],
    ['Petisco sem açúcar', [['SNK-04', 1 / 3], ['SNK-02', 1 / 2], ['BEB-08', 1], ['BEB-04', 1]]],
  ] },
  doce: { nome: 'doce ou sobremesa', combos: [
    ['Sorvete com Nutella', [['DOC-03', 1 / 6], ['DOC-02', 0]]],
    ['Chocolate e biscoito', [['DOC-01', 1], ['DOC-04', 1]]],
    ['Leite com achocolatado e Oreo', [['FRI-01', 1 / 3], ['MER-12', 0], ['DOC-04', 1]]],
  ] },
};
const ocasiaoDe = t => /\b1\b|jant|almoc|comida|refeic/.test(t) ? 'jantar' : /\b2\b|cafe|manha/.test(t) ? 'cafe' : /\b3\b|lanch|petisc|filme|jogo|beliscar/.test(t) ? 'lanche' : /\b4\b|doce|sobremesa|chocolate/.test(t) ? 'doce' : null;
const pessoasDe = t => {
  const n = t.match(/\d{1,2}/);
  if (n) return Math.min(20, Math.max(1, Number(n[0])));
  const ext = [[/so eu|sozinh|\bum\b|\buma\b|eu mesmo|eu mesma/, 1], [/\bdois\b|\bduas\b|casal|eu e (o|a|minha|meu)/, 2], [/\btres\b/, 3], [/\bquatro\b/, 4], [/\bcinco\b/, 5], [/\bseis\b/, 6], [/familia/, 4]];
  for (const [re, v] of ext) if (re.test(t)) return v;
  return null;
};
const zeroDe = { 'BEB-01': 'BEB-08', 'BEB-02': 'BEB-08', 'BEB-03': 'BEB-08' };
const montarCombos = (oc, n) => IDEIAS[oc].combos.map(([nomeC, itens]) => {
  const lista = [];
  for (const [orig, taxa] of itens) {
    const sku = s.prefereZero && zeroDe[orig] ? zeroDe[orig] : orig;
    const p = porSku[sku];
    if (!p || Number(p.Estoque ?? 0) <= 0 || lista.some(x => x[0] === sku) || ((sd.despensas || {})[sessao] || {})[sku]) continue; // o que já tem em casa fica fora do combo
    // quem prefere zero recebe lata zero no lugar da garrafa de 2 L: uma por pessoa
    const q = Math.min(sku !== orig ? n : (taxa ? Math.ceil(n * taxa) : 1), Number(p.Estoque));
    lista.push([sku, q]);
  }
  const total = lista.reduce((t, [sku, q]) => t + q * Number(porSku[sku]['Preço']), 0);
  return { nome: nomeC, lista, total };
}).filter(c => c.lista.length >= 2);
const pedeIdeia = /\bideias?\b|sugest|me sugere|sugere (algo|ai|alguma)|nao sei o que (comer|fazer|comprar|pedir)|o que (eu )?(faco|como|compro) (pra|de|no|hoje)/.test(msg);
if (!saida && (pedeIdeia || s.ideia)) {
  const id = pedeIdeia ? { passo: 0 } : { ...s.ideia };
  s.ideia = null;
  let segue = pedeIdeia;
  if (pedeIdeia) {
    id.ocasiao = ocasiaoDe(msg.replace(/\d/g, ''));
    const pm = msg.match(/(\d{1,2}|uma|um|dois|duas|tres|quatro|cinco|seis) pessoas?|casal|familia|pra mim|so eu/);
    id.pessoas = pm ? pessoasDe(pm[0].replace('pra mim', 'so eu')) : null;
  } else if (id.passo === 1) {
    // só vale resposta curta para a pergunta; "2 coca" é pedido, não opção 2
    id.ocasiao = /^[1-4]$/.test(msg) ? ocasiaoDe(msg) : (!/\d/.test(msg) && msg.split(' ').length <= 4 ? ocasiaoDe(msg) : null);
    segue = !!id.ocasiao;
  } else if (id.passo === 2) {
    id.pessoas = /^\d{1,2}( pessoas?)?$/.test(msg) || /^(so eu|eu|sozinh[oa]|pra mim|eu mesm[oa]|uma?|uma? pessoa|dois|duas|casal|tres|quatro|cinco|seis|familia|(eu e|nos) .{0,20})( pessoas?)?$/.test(msg) ? pessoasDe(msg) : null;
    segue = !!id.pessoas;
  }
  else if (id.passo === 3) {
    const escolha = /^(1|um|o primeiro|primeiro|a primeira|primeira|opcao 1)$/.test(msg) ? 0 : /^(2|dois|o segundo|segundo|a segunda|segunda|opcao 2)$/.test(msg) ? 1 : /^(3|tres|o terceiro|terceiro|a terceira|terceira|opcao 3)$/.test(msg) ? 2 : null;
    const c = escolha !== null ? id.combos[escolha] : null;
    if (c) {
      for (const [sku, q] of c.lista) s.carrinho[sku] = Math.min((s.carrinho[sku] || 0) + q, Number(porSku[sku].Estoque));
      saida = `Fechado, coloquei o combo *${c.nome}*.\n\n` + verCarrinho() + '\n\nQuer tirar ou trocar alguma coisa? É só falar. Para fechar, digite "fechar".';
    }
  }
  // resposta que não é para a pergunta: sai do "me dá uma ideia" e segue o atendimento normal
  if (segue) {
    if (!id.ocasiao) {
      s.ideia = { ...id, passo: 1 };
      saida = 'Bora! É pra quê?\n\n1. Jantar rápido\n2. Café da manhã\n3. Lanche ou petisco (filme, jogo)\n4. Doce ou sobremesa\n\nResponde com o número.';
    } else if (!id.pessoas) {
      s.ideia = { ...id, passo: 2 };
      saida = `Boa, ${IDEIAS[id.ocasiao].nome}. Pra quantas pessoas?`;
    } else {
      const combos = montarCombos(id.ocasiao, id.pessoas);
      s.ideia = { ...id, passo: 3, combos };
      saida = `Pensei em ${combos.length} opções de ${IDEIAS[id.ocasiao].nome} pra ${id.pessoas} ${id.pessoas === 1 ? 'pessoa' : 'pessoas'}:\n\n` +
        combos.map((c, i) => `*${i + 1}. ${c.nome}* (${reais(c.total)})\n\n` + c.lista.map(([sku, q]) => `- ${q}x ${porSku[sku].Produto}`).join('\n')).join('\n\n') +
        `\n\nResponde ${combos.map((_, i) => i + 1).join(', ').replace(/, (\d)$/, ' ou $1')} que eu coloco tudo no carrinho.` + (s.prefereZero ? '\n\nComo você prefere zero, já coloquei refrigerante zero.' : '');
    }
  }
}
if (!saida) {
  if (ehSaudacao) saida = menu();
  else if (pediuDespensa) {
    const d = Object.keys((sd.despensas || {})[sessao] || {}).filter(k => porSku[k]);
    saida = d.length ? '🏠 *Sua despensa* (o que você me disse que tem em casa)\n\n' + d.map(k => `- ${porSku[k].Produto}`).join('\n') + '\n\nSe algo acabar, é só falar (ex.: "acabou o sal").'
      : 'Sua despensa está vazia. Me conta o que você já tem em casa (ex.: "tenho sal e óleo em casa") que eu não ofereço isso nas receitas.';
  }
  else if (pediuCarrinho) saida = verCarrinho() + '\n\nPara fechar, digite "fechar". Para tirar algo, é só falar (ex.: "tira o miojo").';
  else if (pediuLimpar) { s.carrinho = {}; saida = 'Pronto, esvaziei o carrinho. O que você precisa?'; }
  else if (pediuFechar) saida = '__FECHAR__';
  else {
    let cat = null;
    if (/^\d{1,2}$/.test(msg)) cat = cats[Number(msg) - 1] || null;
    if (!cat) cat = cats.find(c => norm(c) === msg) || null;
    if (cat) {
      const lista = produtos.filter(p => p.Categoria === cat).sort((a, b) => a.Produto.localeCompare(b.Produto));
      saida = `*${cat}*\n\n` + lista.map(linha).join('\n') + '\n\nÉ só me falar o que você quer e quantos. Para voltar às categorias, digite "menu".';
    }
  }
}

const totalCarrinho = () => Object.entries(s.carrinho).reduce((t, [sku, q]) => t + (porSku[sku] ? q * Number(porSku[sku]['Preço']) : 0), 0);
if (saida === '__FECHAR__') {
  if (!Object.keys(s.carrinho).length) {
    saida = 'Seu carrinho ainda está vazio. Me fala o que você precisa!';
  } else {
    const valor = Math.round(totalCarrinho() * 100) / 100;
    const resumo = verCarrinho();
    // O Asaas não aceita Pix abaixo de R$ 5,00: avisa antes, em vez de tentar e falhar
    if (valor < 5) { s.ultima = resumo; return [{ json: { usar_ia: false, acao: 'responder', output: resumo + `\n\nO Pix mínimo é R$ 5,00. Faltam ${reais(5 - valor)}. Quer colocar mais alguma coisa?`, sessao } }]; }
    // Já existe um Pix para este mesmo valor: manda o mesmo código, não cria outra cobrança
    if (s.pedido && s.pedido.status === 'aguardando' && Math.abs(s.pedido.valor - valor) < 0.005) {
      saida = resumo + '\n\nSeu Pix já está gerado. Copie o código e pague no app do banco:\n\n' + s.pedido.payload + '\n\nDepois de pagar, me manda "paguei" que eu confiro.';
    } else {
      s.ultima = resumo;
      return [{ json: { usar_ia: false, acao: 'pagar', valor, output: resumo, sessao } }];
    }
  }
}
// Cliente avisou que pagou: confere no Asaas
if (!saida && s.pedido && s.pedido.status === 'aguardando' && /^(paguei|ja paguei|pago|pix pago|ta pago|feito|pronto|ja fiz o pix|fiz o pix)\b/.test(msg)) {
  return [{ json: { usar_ia: false, acao: 'conferir', paymentId: s.pedido.paymentId, output: '', sessao } }];
}

if (saida) {
  s.ultima = saida;
  return [{ json: { usar_ia: false, acao: 'responder', output: saida, sessao } }];
}

// Link de receita: baixa a página e monta o carrinho pelos ingredientes
const url = (msgRaw.match(/https?:\/\/\S+/i) || [])[0];
if (url) return [{ json: { usar_ia: true, acao: 'receita', url, sessao, inicio: Date.now() } }];

// Vai para a IA: manda o catálogo, o carrinho, a última pergunta do atendente e a mensagem
const trocas = sd.trocas || [];
const trocasTexto = trocas.length ? trocas.map((t, i) => `${i + 1}. ${t.ingrediente} -> ${t.risco.startsWith('Alto') ? 'SEM TROCA SEGURA' : t.skus.join(', ')}`).join('\n') : 'nenhuma';
const catTexto = produtos.map(p => `${p.SKU} | ${p.Produto} | ${p.Marca} | ${p.Unidade} | ${p['Como o povo chama'] || ''} | estoque ${p.Estoque ?? 0}`).join('\n');
const carTexto = Object.entries(s.carrinho).map(([sku, q]) => `${sku} x ${q}`).join('\n') || 'vazio';
const prompt = `Você trabalha no Tá Faltando?, um mercadinho de bairro que entrega pelo WhatsApp.
Sua única tarefa é ENTENDER a mensagem do cliente e devolver um JSON. Você não calcula preço nem total.

CATÁLOGO (sku | produto | marca | unidade | como o povo chama | estoque)
${catTexto}

CARRINHO ATUAL (sku x quantidade)
${carTexto}

DESPENSA DO CLIENTE (skus que ele já disse que tem em casa)
${Object.keys((sd.despensas || {})[sessao] || {}).join(', ') || 'vazia'}

SUA ÚLTIMA MENSAGEM PARA O CLIENTE
${(s.ultima || 'nenhuma').slice(0, 800)}

TROCAS APROVADAS (ingrediente que não temos -> sku que pode substituir)
${trocasTexto}

MENSAGEM DO CLIENTE
${msgRaw}

REGRAS
- Entenda apelidos, marcas e o jeito do dia a dia (coca = Coca-Cola, miojo = macarrão instantâneo, bombril = palha de aço, "salgadinho queijo nacho" = Doritos).
- Quantidade por extenso vale (um, dois, três, meia dúzia = 6, uma dúzia = 12). Sem quantidade = 1.
- Se o cliente pedir uma versão que não existe no catálogo (zero, diet, light, sem lactose), NUNCA coloque a versão comum no carrinho: vai em "nao_temos". Em "pedido" copie o que o cliente escreveu.
- A quantidade é sempre em UNIDADES DE VENDA do catálogo (coluna unidade). Se a unidade já tem várias peças (ex.: "bandeja 12 un"), "uma dúzia de ovos" = 1 bandeja, não 12.
- Se o cliente estiver respondendo uma pergunta sua (ex.: "a de lata", "a primeira", "pode ser"), use a sua última mensagem para entender.
- Use SÓ skus que existem no catálogo acima. Nunca invente produto nem sku.
- APELIDO EXATO MANDA: se o que o cliente falou é igual a um dos apelidos de "como o povo chama" de um produto, use ESSE produto. Ex.: "coca" está nos apelidos da Coca-Cola lata, então "2 coca" = 2 Coca-Cola lata. Só use a de 2 litros se o cliente falar "2 litros", "grande", "garrafa" ou "cocão".
- Se o pedido servir para mais de um produto e nenhum apelido bater exato, coloque em "duvidas" com os skus possíveis, em vez de adivinhar.
- Se não temos o produto, coloque em "nao_temos". Se houver algo parecido no catálogo, indique em "troca_sku" (ex.: nescau -> outro achocolatado), mas NÃO coloque a troca no carrinho.
- Se o que o cliente pediu está na lista TROCAS APROVADAS e não existe no catálogo, coloque em "nao_temos" com "troca_n" = número da troca na lista e "troca_sku" = o sku dela (null se for SEM TROCA SEGURA). Ex.: "manjericão" -> troca_n do manjericão. NUNCA coloque a troca direto em "operacoes": o cliente precisa aceitar antes (ex.: pediu "vinho tinto seco" e só temos suave = nao_temos com a troca, não adicionar).
- Fora da lista de trocas, só indique troca_sku se for o MESMO tipo de produto de outra marca (achocolatado por achocolatado). Ingrediente diferente fora da lista = troca_sku null.
- "tira", "remove", "não quero mais" = remover (quantidade null = tirar tudo daquele item). "muda pra 3", "na verdade são 3" = definir.
- Se o cliente disser que JÁ TEM algo em casa ("tenho sal em casa", "arroz eu tenho"), coloque os skus em "tenho" e NÃO coloque no carrinho.
- Se disser que ACABOU algo em casa ("acabou o sal", "o óleo acabou"), coloque os skus em "acabou" e adicione 1 no carrinho (é por isso que ele está pedindo).
- Se o cliente quiser fechar, finalizar ou pagar, "fechar": true.
- Se a mensagem não for pedido (dúvida, conversa), escreva em "resposta" uma frase curta e simpática. Não prometa nada fora do catálogo.

Responda SÓ com um JSON válido, sem nada antes ou depois, neste formato:
{"operacoes":[{"tipo":"adicionar","sku":"BEB-01","quantidade":2,"pedido":"2 coca"}],"duvidas":[{"pedido":"...","skus":["...","..."]}],"nao_temos":[{"pedido":"...","troca_sku":null,"troca_n":null}],"tenho":[],"acabou":[],"fechar":false,"resposta":""}
