const s = sd.sessoes[sessao];
const produtos = sd.catalogo || [];
const porSku = Object.fromEntries(produtos.map(p => [p.SKU, p]));
const reais = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const nome = p => `${p.Produto}${p.Marca && !p.Produto.includes(p.Marca) ? ' ' + p.Marca : ''} (${p.Unidade})`;

// Pedido de versão zero/diet/light (regra do dono): quem pede zero costuma querer seguir sem açúcar.
// 1) se existe a versão zero pedida, usa ela; 2) senão oferece os zeros que existem; 3) e o mesmo sabor comum, avisando do açúcar.
const versaoRe = /\b(zero|diet|light|sem a[cç][uú]car)\b/i;
const semN = x => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const palavras = x => semN(x).replace(/\(.*?\)/g, '').split(/[^a-z]+/).filter(w => w.length > 3 && !['zero', 'diet', 'light', 'lata', 'para', 'refri', 'refrigerante', 'quero', 'sabor', 'acucar'].includes(w));
const ofertaZero = (pedido) => {
  const bebidas = produtos.filter(p => p.Categoria === 'Bebidas' && Number(p.Estoque ?? 0) > 0 && !p['Maior de 18']);
  const ped = palavras(pedido);
  const bate = p => palavras(p.Produto + ' ' + (p['Como o povo chama'] || '')).some(w => ped.some(x => x.includes(w) || w.includes(x)));
  const zeros = bebidas.filter(p => versaoRe.test(p.Produto));
  const zeroMesmo = zeros.find(bate);
  if (zeroMesmo) return zeroMesmo;
  const comum = bebidas.find(p => !versaoRe.test(p.Produto) && bate(p));
  const txt = [`Não temos "${pedido}".`];
  if (zeros.length) txt.push('Para seguir sem açúcar, tenho:\n' + zeros.map(p => `- ${nome(p)}: ${reais(p['Preço'])}`).join('\n'));
  if (comum) txt.push(`${zeros.length ? 'Se preferir o mesmo sabor, tem' : 'Tenho'} ${nome(comum)} por ${reais(comum['Preço'])}, mas atenção: esse tem açúcar.`);
  txt.push(zeros.length || comum ? 'Qual você quer?' : 'Desculpa.');
  return txt.join('\n\n');
};

