// Lê a página da receita: primeiro os dados estruturados (JSON-LD recipeIngredient); se não tiver, o texto da página; se o site bloquear, o nome do prato no link
const sd = $getWorkflowStaticData('global');
const ent = $('Entender mensagem').first().json;
const s = sd.sessoes[ent.sessao];
const produtos = sd.catalogo || [];
const html = String($json.data || '');
let nome = '', ings = [];
for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  try {
    const j = JSON.parse(m[1].trim());
    const lista = [].concat(j, (j && j['@graph']) || []).flat();
    for (const x of lista) {
      const tipo = [].concat((x && x['@type']) || []);
      if (tipo.includes('Recipe')) { nome = x.name || nome; ings = ings.concat(x.recipeIngredient || []); }
    }
  } catch (e) {}
}
let fonte = 'dados da receita (JSON-LD)', conteudo = ings.map(i => '- ' + String(i).replace(/\s+/g, ' ').trim()).join('\n');
if (!ings.length) {
  const texto = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  if (texto.length > 300) { fonte = 'texto da página'; conteudo = texto.slice(0, 6000); }
  else { fonte = 'nome do prato no link (o site não abriu)'; conteudo = ent.url; }
}
sd.ultimaReceita = { url: ent.url, fonte, ingredientes: ings.length, ts: Date.now() };
const trocas = sd.trocas || [];
const trocasTexto = trocas.length ? trocas.map((t, i) => `${i + 1}. ${t.ingrediente} -> ${t.risco.startsWith('Alto') ? 'SEM TROCA SEGURA' : t.skus.join(', ')}`).join('\n') : 'nenhuma';
const catTexto = produtos.map(p => `${p.SKU} | ${p.Produto} | ${p.Marca} | ${p.Unidade} | ${p['Como o povo chama'] || ''} | estoque ${p.Estoque ?? 0}`).join('\n');
const carTexto = Object.entries(s.carrinho).map(([sku, q]) => `${sku} x ${q}`).join('\n') || 'vazio';
const prompt = `Você trabalha no Tá Faltando?, um mercadinho de bairro que entrega pelo WhatsApp.
O cliente mandou o link de uma receita. Sua tarefa é montar o carrinho com os ingredientes que existem no catálogo e devolver um JSON. Você não calcula preço nem total.

CATÁLOGO (sku | produto | marca | unidade | como o povo chama | estoque)
${catTexto}

CARRINHO ATUAL (sku x quantidade)
${carTexto}

TROCAS APROVADAS (ingrediente que não temos -> sku que pode substituir)
${trocasTexto}

RECEITA ${nome ? '"' + nome + '"' : ''} (fonte: ${fonte})
${conteudo}

REGRAS
- Separe os ingredientes em 3 grupos:
  1. PRINCIPAIS que existem no catálogo (o que faz o prato: massa, carne, molho, queijo, legumes): vão em "operacoes" com tipo "adicionar". Quantidade = quantos pacotes/unidades do catálogo a receita precisa (normalmente 1).
  2. BÁSICOS que quase todo mundo tem em casa (sal, açúcar, óleo, azeite, pimenta, alho, cebola, temperos secos) e que existem no catálogo: vão em "em_casa" com o sku. NÃO entram no carrinho.
  3. O que não existe no catálogo: vai em "nao_temos". Se estiver na lista TROCAS APROVADAS, preencha "troca_n" e "troca_sku" (null se SEM TROCA SEGURA). Fora da lista, troca_sku null.
- Use SÓ skus que existem no catálogo. Nunca invente produto nem sku. Não repita o mesmo sku em grupos diferentes.
- Ignore água e itens que não são comida.
- Em "receita" escreva o nome do prato. Se a fonte for o nome do prato no link, deduza os ingredientes típicos desse prato e escreva em "aviso": "Não consegui abrir o site, montei pelo nome do prato.".

Responda SÓ com um JSON válido, sem nada antes ou depois, neste formato:
{"receita":"Macarrão à bolonhesa","aviso":"","operacoes":[{"tipo":"adicionar","sku":"MER-01","quantidade":1,"pedido":"500 g de espaguete"}],"em_casa":[{"pedido":"sal","sku":"MER-07"}],"nao_temos":[{"pedido":"manjericão","troca_sku":null,"troca_n":null}],"duvidas":[],"fechar":false,"resposta":""}`;
return [{ json: { prompt, sessao: ent.sessao } }];

// Termo que a IA não reconheceu e não tem troca: procura na Wikipédia para descobrir o que é (grátis, sem chave)
const sd = $getWorkflowStaticData('global');
const texto = String($input.first().json.text || '');
let ia = null;
try { ia = JSON.parse(texto.replace(/```json|```/g, '').trim()); } catch (e) { ia = null; }
const semN = x => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const stop = ['um', 'uma', 'dois', 'duas', 'tres', 'quatro', 'cinco', 'seis', 'meia', 'duzia', 'quero', 'me', 've', 'manda', 'traz', 'coloca', 'mais', 'tambem', 'e', 'o', 'a', 'os', 'as', 'de', 'pra', 'por', 'favor', 'oi', 'tem', 'voces', 'vcs'];
const limpar = x => { const tk = semN(x).replace(/\d+/g, ' ').split(/[^a-z]+/).filter(Boolean); while (tk.length && stop.includes(tk[0])) tk.shift(); while (tk.length && stop.includes(tk[tk.length - 1])) tk.pop(); return tk.join(' '); };
if (sd.pesquisasVer !== 3) { sd.pesquisas = {}; sd.pesquisasVer = 3; }
const alvo = ia && Array.isArray(ia.nao_temos) ? ia.nao_temos.find(n => !n.troca_sku && !n.troca_n && !/\b(zero|diet|light|sem a[cç][uú]car|sem lactose)\b/i.test(n.pedido || '') && limpar(n.pedido).length >= 3 && !sd.pesquisas[limpar(n.pedido)]) : null;
if (!alvo || $('Entender mensagem').first().json.acao === 'receita') return [{ json: { pesquisar: false } }];
return [{ json: { pesquisar: true, termo: limpar(alvo.pedido) } }];

