// Guarda o que a pesquisa achou (vale para todos os clientes, sem pesquisar de novo). Sem trecho que explique, não inventa.
const sd = $getWorkflowStaticData('global');
const { termo, titulos } = $('Montar pergunta da pesquisa').first().json;
const r = $input.first().json || {};
