if (res) {
  const titulo = titulos[(Number(res.trecho) || 1) - 1] || titulos[0] || '';
  const ok = res.o_que_e && res.o_que_e !== 'null' && titulo;
  sd.pesquisas[termo] = ok
    ? { o_que_e: String(res.o_que_e).replace(/\.+$/, '').replace(/^\p{Lu}(?!\p{Lu})/u, c => c.toLowerCase()).slice(0, 120), sku: porSku[res.sku] ? res.sku : null, fonte: titulo, url: 'https://pt.wikipedia.org/wiki/' + encodeURIComponent(titulo.replace(/ /g, '_')), ts: Date.now() }
    : { o_que_e: null, sku: null, ts: Date.now() };
  const ks = Object.keys(sd.pesquisas); if (ks.length > 300) delete sd.pesquisas[ks[0]];
}
return [{ json: { ok: !!(res && res.o_que_e) } }];

// Foto da lista ou áudio: manda o arquivo para o Gemini transcrever o pedido do jeito que o cliente escreveu ou falou
const it = $input.first();
const bin = it.binary || {};
const parts = [];
let tipo = 'foto';
for (const k of Object.keys(bin)) {
  const mime = bin[k].mimeType || '';
  if (!/^(image|audio)\//.test(mime)) continue;
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  parts.push({ inline_data: { mime_type: mime, data: buf.toString('base64') } });
  if (mime.startsWith('audio')) tipo = 'audio';
}
const legenda = it.json.legenda || '';
const prompt = `Você é atendente de um mercadinho no Brasil. O cliente mandou ${tipo === 'audio' ? 'um áudio' : 'uma foto da lista de compras (pode ser escrita à mão)'}${legenda ? ` com a mensagem "${legenda}"` : ''}.
Transcreva SÓ o pedido, do jeito que o cliente escreveu ou falou, um item por linha, com a quantidade se tiver (ex.: "2 coca"). Não troque nomes nem corrija marcas.
Se não der para ler ou entender um item, escreva "[não entendi]" nessa linha. Se não houver pedido nenhum, responda só: NADA
Responda só com as linhas, sem comentário.`;
return [{ json: { ...it.json, tipo, temArquivo: parts.length > 0, body: { contents: [{ parts: [{ text: prompt }, ...parts] }], generationConfig: { temperature: 0.1 } } } }];

